import React, { useEffect, useState } from "react";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
// import axios from "axios";
import api from "../api";  // relative path to api.js
import { encryptData, decryptData } from "../utils/encryption";
import "../styles/main.css";

const SERVER_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";


export default function AdminManageHome() {
  const [data, setData] = useState({
    bannerVideos: [],
    welcomeText: "",
    activities: [],
    threeCol: [],
    testimonialVideos: [],
    threeColumnSection: {
      latestNewsHeading: "",
      latestNewsParagraph: "",
      activityCalendar: "",
      calendarButtonLink: "#",
      video: "",
    },
  });
  const [calendarFile, setCalendarFile] = useState(null);
  const [loading, setLoading] = useState(false);

  // Fetch home content
  // useEffect(() => {
  //   api
  //     .get("/api/home")
  //     .then((res) => {
  //       setData((prev) => ({
  //         ...prev,
  //         ...res.data,
  //         threeColumnSection: {
  //           latestNews: res.data.threeColumnSection?.latestNews || "",
  //           latestNewsParagraph:
  //             res.data.threeColumnSection?.latestNewsParagraph || "",
  //           activityCalendar: res.data.threeColumnSection?.activityCalendar || "",
  //           calendarButtonLink:
  //             res.data.threeColumnSection?.calendarButtonLink || "#",
  //           video: res.data.threeColumnSection?.video || "",
  //         },
  //       }));
  //     })
  //     .catch((err) => console.error("Error loading home data:", err));
  // }, []);
    useEffect(() => {
      api.get("/api/home")
      .then((res) => {
        const f = res.data;

        setData({
          bannerVideos: f.bannerVideos || [],
          activities: f.activities || [],
          testimonialVideos: f.testimonialVideos || [],
          welcomeText: decryptData(f.welcomeText || ""),

          threeColumnSection: {
            latestNewsHeading: decryptData(
              f.threeColumnSection?.latestNewsHeading || ""
            ),
            latestNewsParagraph: decryptData(
              f.threeColumnSection?.latestNewsParagraph || ""
            ),
            activityCalendar: f.threeColumnSection?.activityCalendar || "",
            video: f.threeColumnSection?.video || ""
          }
        });
      })
      .catch((err) => console.error("Error loading home data:", err));
    }, []);


  // File upload for banner, activities, testimonials
  const handleFileUpload = async (e, section) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append("file", file);

    try {
      const token = localStorage.getItem("token");
      if (!token) {
        alert("You must log in first!");
        return;
      }
      const res = await api.post(
        "/api/admin/home",
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
          params: { section },
        }
      );

      if (res.data?.content?.[section]) {
        setData((prev) => ({
          ...prev,
          [section]: res.data.content[section],
        }));
      }
    } catch (err) {
      console.error("Upload failed:", err);
      alert("Upload failed. Check console for details.");
    }
  };

  // Delete media
  const handleDelete = (key, index) => {
    setData((prev) => ({
      ...prev,
      [key]: prev[key].filter((_, i) => i !== index),
    }));
  };

